``` {.python .cell-code}
def tiling_memo(n):
    """Same recursion. Each (state, i) is stored once: O(n) calls instead of a tree."""
    mf, mg = [-1] * (n + 1), [-1] * (n + 1)

    def g(i):
        if i <= 0:
            return 0
        if i == 1:
            return 1
        if mg[i] < 0:
            mg[i] = g(i - 1) + f(i - 1)
        return mg[i]

    def f(i):
        if i == 0 or i == 1:
            return 1
        if mf[i] < 0:
            mf[i] = f(i - 1) + f(i - 2) + 2 * g(i - 2)
        return mf[i]

    return f(n)
```
