def tiling_two_state(n):
    """Tabulation. Fill f and g from the left; every cell is one of the recursive calls."""
    f = [1, 1] + [0] * max(0, n - 1)
    g = [0, 1] + [0] * max(0, n - 1)
    for i in range(2, n + 1):
        f[i] = (f[i - 1] + f[i - 2] + 2 * g[i - 2]) % MOD
        g[i] = (g[i - 1] + f[i - 1]) % MOD
    return f[n]
```
