int tilingTable(int n) {
    vector<long long> f(n + 1), g(n + 1);
    f[0] = 1; f[1] = 1; g[1] = 1;
    for (int i = 2; i <= n; ++i) {
        f[i] = (f[i - 1] + f[i - 2] + 2 * g[i - 2]) % MOD;
        g[i] = (g[i - 1] + f[i - 1]) % MOD;
    }
    return (int)f[n];
}
