def num_tilings(n):
    """Optimal for n ≤ 1000: g is eliminated, and only the last three f values are alive."""
    if n == 1:
        return 1
    a, b, c = 1, 1, 2               # f[0], f[1], f[2]
    for _ in range(3, n + 1):
        a, b, c = b, c, (2 * c + a) % MOD
    return c
```
