int numTilings(int n) {                      // optimal: three rolling values of f
    if (n == 1) return 1;
    long long a = 1, b = 1, c = 2;
    for (int i = 3; i <= n; ++i) { long long nxt = (2 * c + a) % MOD; a = b; b = c; c = nxt; }
    return (int)c;
}
