def tiling_matrix(n):
    """O(log n). The companion matrix of f[n] = 2 f[n-1] + 0 f[n-2] + f[n-3]."""
    def mul(A, B):
        return [[sum(A[i][k] * B[k][j] for k in range(3)) % MOD for j in range(3)] for i in range(3)]
    M = [[2, 0, 1], [1, 0, 0], [0, 1, 0]]
    R = [[1, 0, 0], [0, 1, 0], [0, 0, 1]]
    e = max(n - 2, 0)
    while e:
        if e & 1:
            R = mul(R, M)
        M = mul(M, M)
        e >>= 1
    # (f[n], f[n-1], f[n-2]) = R * (f[2], f[1], f[0])
    return (R[0][0] * 2 + R[0][1] * 1 + R[0][2] * 1) % MOD if n >= 2 else 1

def tiling_place(n):
    """Oracle: place every domino and tromino. Exponential, and not the DP."""
    return len(tilings(n))

for n in range(1, 9):
    assert tiling_rec(n) == tiling_memo(n) == tiling_two_state(n) == num_tilings(n) == tiling_matrix(n) == tiling_place(n), n
assert [num_tilings(n) for n in (1, 2, 3, 4, 5)] == [1, 2, 5, 11, 24]
assert num_tilings(1000) == tiling_matrix(1000)
print("n = 1000:", num_tilings(1000))
