const long long MOD = 1'000'000'007;
using Mat = array<array<long long, 3>, 3>;
Mat mul(const Mat& A, const Mat& B) {
    Mat C{};
    for (int i = 0; i < 3; ++i)
        for (int k = 0; k < 3; ++k)
            for (int j = 0; j < 3; ++j) C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD;
    return C;
}
int tilingMatrix(int n) {
    if (n < 2) return 1;
    Mat M{{{2, 0, 1}, {1, 0, 0}, {0, 1, 0}}};
    Mat R{{{1, 0, 0}, {0, 1, 0}, {0, 0, 1}}};
    for (int e = n - 2; e; e >>= 1) {
        if (e & 1) R = mul(R, M);
        M = mul(M, M);
    }
    return (int)((R[0][0] * 2 + R[0][1] + R[0][2]) % MOD);
}
```
