``` {.python .cell-code}
def _pts(a):
    mx = max(a)
    pts = [0] * (mx + 1)
    for x in a:
        pts[x] += x
    return pts

def boredom_rec(a):
    """Recursion on the value line. f(v) = best using values 1..v."""
    pts = _pts(a)

    def f(v):
        if v <= 0:
            return 0
        return max(f(v - 1), pts[v] + f(v - 2))

    return f(len(pts) - 1)
```
