def unique_memo(grid):
    """Same recursion. One stored answer per cell, so each cell is entered once."""
    R, C = len(grid), len(grid[0])
    memo = [[-1] * C for _ in range(R)]

    def go(r, c):
        if r >= R or c >= C or grid[r][c]:
            return 0
        if (r, c) == (R - 1, C - 1):
            return 1
        if memo[r][c] < 0:
            memo[r][c] = go(r + 1, c) + go(r, c + 1)
        return memo[r][c]

    return go(0, 0)
```
:::


