int uniMemo(int r, int c, const vector<vector<int>>& g, vector<vector<int>>& memo) {
    int R = g.size(), C = g[0].size();
    if (r >= R || c >= C || g[r][c]) return 0;
    if (r == R - 1 && c == C - 1) return 1;
    if (memo[r][c] < 0) memo[r][c] = uniMemo(r + 1, c, g, memo) + uniMemo(r, c + 1, g, memo);
    return memo[r][c];
}
