``` {.python .cell-code}
def unique_table(grid):
    """Tabulation. dp[r][c] is go(r, c) filled from the goal's direction: top-left first,
    because each cell reads the cell above and the cell to the left."""
    R, C = len(grid), len(grid[0])
    dp = [[0] * C for _ in range(R)]
    if grid[0][0] == 0:
        dp[0][0] = 1
    for r in range(R):
        for c in range(C):
            if grid[r][c] or (r, c) == (0, 0):
                continue
            dp[r][c] = (dp[r - 1][c] if r else 0) + (dp[r][c - 1] if c else 0)
    return dp[-1][-1]
```
:::


##### C++

```cpp
int uniTable(const vector<vector<int>>& g) {
    int R = g.size(), C = g[0].size();
    vector<vector<long long>> dp(R, vector<long long>(C));
    if (!g[0][0]) dp[0][0] = 1;
    for (int r = 0; r < R; ++r)
        for (int c = 0; c < C; ++c) {
            if (g[r][c] || (!r && !c)) continue;
            dp[r][c] = (r ? dp[r - 1][c] : 0) + (c ? dp[r][c - 1] : 0);
        }
    return (int)dp[R - 1][C - 1];
}
```
:::

