def min_path_rec(g):
    """Recursion. Cheapest path from (r, c) to the goal, stepping down or right."""
    R, C = len(g), len(g[0])

    def f(r, c):
        if r == R or c == C:
            return math.inf
        if r == R - 1 and c == C - 1:
            return g[r][c]
        return g[r][c] + min(f(r + 1, c), f(r, c + 1))

    return f(0, 0)
```
